extension Fuzz {
extension ArrayElementListSyntax {
  public init(expressions: [ExprSyntax]
) {
    let lastIndex = expressions.count - 1
    let elements = expressions.enumerated().map  /* c */ { index, expression in
      let element = ArrayElementSyntax(expression: expression)
      if index < lastIndex {
        return element./*c*/ensuringTrailingComma()
      } else {
        return element
      }
    }
    self.init(elements)
  }
}
}

